import { Link } from 'react-router-dom'

import { Box, Card, CardActionArea, Chip, Stack, Typography } from '@mui/material'

import getImgFromHtml from 'src/utils/getImgFromHtml'
import { htmlToPlainTextWithDOM } from 'src/utils/htmlToPlainText'

import type { GetRecentActivityResDto } from 'src/models/activity'

interface ActivityPreviewCardProps {
  showClubInfo?: boolean
  activity: GetRecentActivityResDto
}

const ActivityPreviewCard = ({ showClubInfo, activity }: ActivityPreviewCardProps) => {
  const plainText = htmlToPlainTextWithDOM(activity.note)
  const imageUrl = getImgFromHtml(activity.note) || ''
  const dateSource = activity.type === 'activity-post' ? activity.createdAt : activity.startAt
  const date = dateSource ? new Date(dateSource).toLocaleDateString() : ''

  return (
    <Card sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      <CardActionArea
        component={Link}
        to={
          activity.type === 'conference-round'
            ? `/club/${activity.club.id}/conference/round/${activity.id}`
            : `/club/${activity.club.id}/post/${activity.id}`
        }
        sx={{ height: '100%' }}
      >
        <Stack spacing={1.2} sx={{ padding: 2, flex: 1, display: 'flex', flexDirection: 'column' }}>
          {/* 동아리 정보 */}
          {showClubInfo && (
            <Stack marginBottom={0.4}>
              <Typography
                variant="body1"
                sx={{
                  color: 'text.primary',
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap'
                }}
              >
                {activity.club.name}
              </Typography>
              {activity.club.description && (
                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {activity.club.description}
                </Typography>
              )}
            </Stack>
          )}

          {/* 컨퍼런스 타이틀 */}
          <Typography
            variant="h4"
            sx={{
              color: 'text.primary',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap'
            }}
          >
            {activity.title}
          </Typography>

          {/* 카테고리 칩들 */}
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
            {activity.categories &&
              activity.categories.map((category, index) => (
                <Chip
                  key={index}
                  label={category}
                  size="small"
                  variant="filled"
                  sx={{
                    height: '24px',
                    fontSize: '0.75rem',
                    '& .MuiChip-label': {
                      padding: '0 8px'
                    }
                  }}
                />
              ))}
          </Box>

          {/* Note 텍스트 (최대 2줄) */}
          <Typography
            variant="body1"
            sx={{
              minHeight: 'calc(1.5em * 2)', // 1줄은 1.5em이므로 2줄 높이
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              color: 'text.primary'
            }}
          >
            {plainText}
          </Typography>

          {/* 이미지 영역 */}
          {imageUrl ? (
            <Box
              component="img"
              src={imageUrl}
              alt="활동 사진"
              sx={{
                width: '100%',
                height: '200px',
                objectFit: 'cover',
                borderRadius: 1
              }}
            />
          ) : (
            <Box
              sx={{
                width: '100%',
                height: '200px'
              }}
            />
          )}

          {/* 날짜 */}
          <Typography variant="caption" sx={{ color: 'text.secondary', marginTop: 'auto' }}>
            {date}
          </Typography>
        </Stack>
      </CardActionArea>
    </Card>
  )
}

export default ActivityPreviewCard
